import{d as g,C as e,o as h,c as d,j as a,a as n,E as r,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"中庸·第15章","description":"《中庸》第 15 章——行远必自迩，登高必自卑：由《常棣》之诗说家和，父母其顺矣乎。","frontmatter":{"title":"中庸·第15章","description":"《中庸》第 15 章——行远必自迩，登高必自卑：由《常棣》之诗说家和，父母其顺矣乎。","category":"guide","aliases":["第15章","中庸第15章","行远自迩"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-15.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-15.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-15.md"},x=g({...m,setup(p){const o=[{id:"ziEr",label:"行远必自迩 · 登高必自卑",showLabel:!0,sentences:[["君子之道，",{text:"辟如",glossary:"piru"},"行远必",{text:"自迩",glossary:"zier"},"，辟如登高必",{text:"自卑",glossary:"zibei"},"。"]],note:"「君子之道，辟如行远必自迩，辟如登高必自卑」——辟如同「譬如」；自迩，从近处起步；自卑，从低处开始（此处「卑」指起点低，非「自卑感」）。以行路、登高为喻：道的功夫必从最近、最低处做起。此句与上章「造端乎夫妇」一脉相承，也与下节「家和而父母顺」互为表里。"},{id:"changdi",label:"妻子好合 · 兄弟既翕 · 父母其顺矣乎",showLabel:!0,sentences:[["《诗》曰：“妻子",{text:"好合",glossary:"haohe"},"，如鼓瑟琴；兄弟既",{text:"翕",glossary:"xi"},"，和乐且",{text:"耽",glossary:"dan"},"；宜尔室家；乐尔妻",{text:"帑",glossary:"nu"},"。”子曰：“父母其顺矣乎！”"]],note:"引《诗》「妻子好合，如鼓瑟琴；兄弟既翕，和乐且耽；宜尔室家；乐尔妻帑（帑＝孥，妻子儿女）」——夫妻和睦如琴瑟相和，兄弟融洽而和乐，使家室相宜、妻儿快乐。孔子因而叹：「父母其顺矣乎！」——这样，父母大概就顺心了吧。此章言「和」之效：家和人顺，正是行道之始。"}],t=[{id:"piru",term:"辟如",pinyin:"pì rú",meaning:"譬如。辟：同「譬」。"},{id:"zier",term:"自迩",pinyin:"zì ěr",meaning:"从近处开始。迩：近。"},{id:"zibei",term:"自卑",pinyin:"zì bēi",meaning:"从低处开始。卑：低。此处是方法，非「自卑感」。"},{id:"haohe",term:"好合",pinyin:"hǎo hé",meaning:"和睦相处。"},{id:"xi",term:"翕",pinyin:"xī",meaning:"合、和好。朱注：「翕，亦合也。」"},{id:"dan",term:"耽",pinyin:"dān",meaning:"快乐。《诗》作「湛」，亦音 dān。"},{id:"nu",term:"帑",pinyin:"nú",meaning:"子孙，同「孥」。「乐尔妻帑」即让妻儿安乐。"}];return(c,i)=>{const s=e("DaoTextReading"),l=e("DaoKeywordCards");return h(),d("div",null,[i[0]||(i[0]=a("h1",{id:"中庸·第15章",tabindex:"-1"},[n("中庸·第15章 "),a("a",{class:"header-anchor",href:"#中庸·第15章","aria-label":'Permalink to "中庸·第15章"'},"​")],-1)),i[1]||(i[1]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[n("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),i[2]||(i[2]=a("p",null,"第十五章只两节：先说「行远必自迩，登高必自卑」；再引《常棣》之诗，从夫妻、兄弟之和，说到「父母其顺矣乎」。默认竹简沉浸通读；切「经典阅读」可点生词。",-1)),r(s,{colophon:"行远自迩 · 登高自卑 · 父母其顺",tone:"ink",sections:o,glossary:t,"default-mode":"slips","aria-label":"中庸·第15章 原文"}),i[3]||(i[3]=a("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[n("【原典层】注音与字词 "),a("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),r(l,{items:[{term:"自迩",pinyin:["zì","ěr"],meaning:"从近处开始。迩：近。"},{term:"自卑",pinyin:["zì","bēi"],meaning:"从低处开始。卑：低。此处是方法，不是「自卑感」。"},{term:"好合",pinyin:["hǎo","hé"],meaning:"和睦相处。「妻子好合，如鼓瑟琴」。"},{term:"翕",pinyin:["xī"],meaning:"合、和好。「兄弟既翕」。"},{term:"耽",pinyin:["dān"],meaning:"快乐。《诗》作「湛」。"},{term:"帑",pinyin:["nú"],meaning:"子孙，同「孥」。「乐尔妻帑」即让妻儿安乐。"}]}),i[4]||(i[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>行远必自迩 · 登高必自卑</strong>：君子的道，就像走远路必从近处起步，登高必从低处开始。</p><p><strong>妻子好合 · 兄弟既翕 · 父母其顺矣乎</strong>：《诗经》说：「妻子和睦，如弹瑟琴；兄弟和好，和乐且欢；使你的室家和顺，使你的妻儿安乐。」孔子说：「这样，父母大概就顺心了呀！」</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第十五章两节：</p><ol><li><strong>行远必自迩，登高必自卑</strong>——功夫从最近处开始</li><li><strong>引《常棣》</strong>——夫妻好合、兄弟既翕，最后落在「父母其顺矣乎」</li></ol><p>前一句是原则，后一句是这原则的具体内容：<strong>自迩，就从家开始。</strong></p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它是第 12、13 章的延伸</strong>：第 12 章说「造端乎夫妇」，第 13 章说「道不远人」，本章给出一条可执行的次序——<strong>行远自迩、登高自卑</strong>。</li><li><strong>「自卑」须与「自卑感」分开</strong>：这里的「卑」是起点低，不是自我贬低。<strong>低处起步</strong>恰恰是方法。</li><li><strong>它把「家」当作道的试验场</strong>：家是最早、最近、也最难的地方；家和则父母顺，这不是教化口号，而是次序——<strong>能近处做好的，才有资格谈远处</strong>。</li><li><strong>它与第 14 章「素其位」互补</strong>：一个是空间上的「安于本位」，一个是次序上的「从近处起」。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>检查次序</strong>：我想做的事，起点选在最近处了吗？还是直接跳去远方？</li><li><strong>从家里起步</strong>：最能验证功夫的地方，往往最近。</li><li><strong>别把「自卑」误读成贬低</strong>：从低处起，是路径选择。</li><li><strong>一句话复盘</strong>：我能把「行远自迩」落到本周一件具体的事上吗？</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>君子之道有个最朴素的次序：<strong>走远路的人，一定从近处起步；登高的人，一定从低处开始。</strong></p><p>接着引用《诗经》讲家：夫妻和睦如弹琴鼓瑟，兄弟和好、和乐且欢——把家安顿好，妻儿安乐，那么「<strong>父母其顺矣乎</strong>」？父母的顺心，是这一切的结果。</p><p>这一章只有两句，但它给出的路径很清楚：<strong>先近后远，先家后天下。</strong> 想做好大事的人，先从最近的那一件事、最近的一个人开始。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「行远必自迩，登高必自卑」——我现在想做的事，起点选在最近处了吗？</li><li>「父母其顺矣乎」——「自迩」的第一站，在我家里吗？</li><li>我有没有把「自卑」误读成「自我贬低」？这两者的差别在哪里？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-14">中庸·第14章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-16">中庸·第16章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',23))])}}});export{y as __pageData,x as default};
